#!/bin/bash
set -e
DEST="$HOME/local/repos/CppKAI/ContinuationMobilityDemo"
SRC="/mnt/d/Downloads"

# Copy and patch Animation HTML
anim=$(ls -t "$SRC"/ContinuationMobilityAnimation*.html 2>/dev/null | head -1)
if [ -n "$anim" ]; then
    cp "$anim" "$DEST/ContinuationMobilityAnimation.html"
    echo "Copied Animation"
else
    echo "MISSING: ContinuationMobilityAnimation.html"
    exit 1
fi

fsed -i 's|<a class="page-link" href="./ContinuationMobilityDemo.html">System View</a>|<a class="page-link" href="./ContinuationMobilityDemo.html">System View</a>\n      <a class="page-link" href="./Description.html">Description</a>|g' \
    "$DEST/ContinuationMobilityAnimation.html"
echo "Patched Animation nav"

echo '' | base64 -d > "$DEST/ContinuationMobilityDemo.html"
echo "Written ContinuationMobilityDemo.html"

echo '' | base64 -d > "$DEST/Description.html"
echo "Written Description.html"

git -C "$HOME/local/repos/CppKAI" add ContinuationMobilityDemo/
git -C "$HOME/local/repos/CppKAI" commit -m "Add Description and System View tabs"
git -C "$HOME/local/repos/CppKAI" push
echo "Done."
